{
  "103:1": "وَٱلْعَصْرِ",
  "103:2": "إِنَّ ٱلْإِنسَٰنَ لَفِى خُسْرٍ",
  "103:3": "إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ"
}

{"connection_id": "BC-58d8fa9e77033fb6e25d", "ref": "Augustine, Confessions 11.20.26", "target": "sec2", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "Past, present, and future held in the mind", "note": "The commentary argues that lived time consists of joined pieces rather than a single flat flow; Augustine describes a present of remembered past, attended present, and expected future, offering a later Christian account of how those parts are connected."}
{"connection_id": "BC-1e80233235f29fb08d49", "ref": "Didache 16.1", "target": "sec2", "tradition": "incil", "kind": "motif", "basis": "lamps burning; be ready because the hour is unknown", "note": "The commentary joins night/day divisions to patience and waiting; the Didache tells its readers to watch their lives, keep lamps lit, and be ready because the Lord's hour is unknown, giving the temporal image an early Christian practice of vigilance."}
{"connection_id": "BC-a6be5333c52ddb93137e", "ref": "Didache 16:1", "target": "sec2", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "Keep watch because the hour is unknown", "note": "The commentary stretches patience through uncertain time before the final contraction; the Didache tells believers to watch their lives and keep lamps ready since they do not know the Lord's hour."}
{"connection_id": "BC-a589f434e2ce847f8c73", "ref": "Didache 16:2", "target": "sec2", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "Meet often; faith must endure to the end", "note": "The commentary connects repeated meetings among people with the need to remain through time; the Didache urges frequent gathering for the soul and says a lifetime of faith is of no benefit unless completed at the end."}
{"connection_id": "BC-7fa89cb72e912a7b29a1", "ref": "Didache 4.3", "target": "sec2", "tradition": "incil", "kind": "motif", "basis": "reprove one another in peace", "note": "The commentary's reciprocal counsel is tied to haqq; the Didache directs members to reprove each other without anger and in peace, specifying both correction and its manner."}
{"connection_id": "BC-f5332e9f594d8d900a63", "ref": "Didache 8.3", "target": "sec2", "tradition": "incil", "kind": "motif", "basis": "pray the Lord's Prayer three times a day", "note": "The commentary sets dawn/evening and night/day as named units; the Didache schedules a repeated Christian prayer three times through the day, giving temporal divisions a liturgical practice."}
{"connection_id": "BC-3a9f336c3f3daeeedb87", "ref": "Gospel of Thomas 59", "target": "sec2", "tradition": "incil", "kind": "motif", "basis": "seek the Living One while alive", "note": "The commentary emphasizes the shortness of life and its closing encounter; this saying urges seeking the Living One before death, turning limited lifetime into an immediate obligation. English wording varies by translation."}
{"connection_id": "BC-c88a0667037c98d78250", "ref": "SBLGNT:1Cor.13.6", "target": "sec2", "tradition": "incil", "kind": "motif", "basis": "love rejoices with truth", "note": "The commentary couples mutual counsel with haqq; Paul makes truth the object of love's rejoicing, locating truth inside a durable ethical relation."}
{"connection_id": "BC-fb0d2b3383d226dce09b", "ref": "SBLGNT:1Cor.13.7", "target": "sec2", "tradition": "incil", "kind": "motif", "basis": "love endures all things", "note": "The commentary couples haqq with sabr; Paul describes love as enduring all things, placing endurance inside the same ethical frame as truth in the preceding verse."}
{"connection_id": "BC-a517e9e8a29672059f11", "ref": "SBLGNT:1Cor.15.32", "target": "sec2", "tradition": "incil", "kind": "karsi_anlati", "basis": "If the dead do not rise, eat and drink", "note": "The commentary reports deniers who treat mortal time as final; Paul voices the practical conclusion of denying resurrection, eating and drinking because tomorrow brings death, then challenges that premise in his resurrection argument."}
{"connection_id": "BC-c6144ef4a3db1f9751fe", "ref": "SBLGNT:1Cor.15.58", "target": "sec2", "tradition": "incil", "kind": "motif", "basis": "steadfast work is not in vain", "note": "The commentary says human beings lose time except through faith and good deeds; in a chapter about resurrection, Paul urges steadfast work because labor in the Lord is not in vain, answering the fear that time erases action."}
{"connection_id": "BC-629ba27599aa551dbbae", "ref": "SBLGNT:1Cor.15.58", "target": "sec2", "tradition": "incil", "kind": "motif", "basis": "Steadfastness joined to enduring work", "note": "The commentary's remaining group combines persistence with righteous deeds; Paul concludes his resurrection argument by telling believers to be steadfast and always active in the Lord's work because that labor is not futile."}

